---@return table[]
function QuestRewardVo:GetShowRewardData()
    local rewardData = {}
    local items = CfUtils.Split(self.showItem)
    local showItemTags = CfUtils.Split(self.showItemTag)
    local showItemNums = CfUtils.Split(self.showItemNum)
    local rewardData = {}
    if items and showItemTags and showItemNums then
        for i = 1, #items do
            local reward = {
                id = checkInt(items[i]),
                num = checkInt(showItemNums[i]),
                type = checkInt(showItemTags[i]),
            }
            table.insert(rewardData, reward)
        end
    end
    return rewardData
end

function QuestRewardVo:GetRewards()
    local rewards = {}
    table.link(rewards, parse_rewards(self:RegularSplit(self.fristRewards), self:RegularSplit(self.fristRewardsNum)))
    table.link(rewards, parse_rewards(self:RegularSplit(self.regularReward), self:RegularSplit(self.regularRewardNum)))
    table.link(rewards, parse_rewards(self:RegularSplit(self.rewardID), self:RegularSplit(self.rewardNum)))
    table.link(rewards, parse_rewards(self:RegularSplit(self.raidRewardID), self:RegularSplit(self.raidRewardNum)))
    return rewards
end

function QuestRewardVo:RegularSplit(ids)
    ids = string.gsub(ids, ",", ";")
    ids = string.gsub(ids, "|", ";")
    return ids
end

